"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["32986"],{49509(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.tipo_conceito.conflito_de_concorrencia","status":409,"titulo":"Tipo de conceito alterado concorrentemente"},"descricao":{"codigo":"uniplus.configuracao.tipo_conceito.conflito_de_concorrencia","requisitos":[],"oQueAconteceu":["Duas altera\xe7\xf5es do mesmo tipo de conceito chegaram ao mesmo tempo, ou os valores categ\xf3ricos do tipo foram substitu\xeddos por outra atualiza\xe7\xe3o durante a grava\xe7\xe3o. S\xf3 uma delas p\xf4de ser aplicada, e esta foi recusada. Nada deste pedido foi gravado.","A atualiza\xe7\xe3o (`PUT /api/configuracao/admin/tipos-conceito/{id}`) substitui por inteiro os valores categ\xf3ricos do tipo; sem a recusa, uma das edi\xe7\xf5es apagaria a outra sem que ningu\xe9m percebesse. Esta \xe9 a \xfanica opera\xe7\xe3o do cadastro que responde com este c\xf3digo.","A recusa descreve uma corrida que j\xe1 passou, n\xe3o um estado que permanece: a resposta traz `retryable: true`, e repetir o pedido pode dar certo. Ela vem por \xfaltimo, depois da leitura do corpo, da confer\xeancia do `id` do corpo contra o da rota, da valida\xe7\xe3o do conte\xfado (422) e da busca do tipo: com um `{id}` que n\xe3o existe prevalece [tipo de conceito n\xe3o encontrado](/erros/uniplus.configuracao.tipo_conceito.nao_encontrado), e com o conte\xfado do corpo inv\xe1lido prevalece a recusa de valida\xe7\xe3o correspondente; corpo que n\xe3o desserializa e `id` do corpo diferente do da rota s\xe3o recusados antes de tudo, com 400."],"comoResolver":["Repita o pedido de atualiza\xe7\xe3o. Se a recusa se repetir, consulte o tipo (`GET /api/configuracao/tipos-conceito/{id}`, que traz os tipos ativos) para ver o que a outra altera\xe7\xe3o gravou e refa\xe7a o pedido sobre o conte\xfado atual, porque a atualiza\xe7\xe3o substitui os valores categ\xf3ricos por inteiro."],"ondeAparece":["Atualiza\xe7\xe3o de um tipo de conceito"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Tipo conceito"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"fd5ea0ff72951399d2b2c1a4f29aeb3ea415db44"}}')}}]);